  ('What is the capital of Poland?', array['Krakow','Warsaw','Gdansk','Wroclaw'], 1, 'easy'),
  ('What is the capital of the Netherlands?', array['Rotterdam','The Hague','Amsterdam','Utrecht'], 2, 'medium'),
