  ('What is the capital of Vietnam?', array['Ho Chi Minh City','Hanoi','Da Nang','Hue'], 1, 'medium'),
  ('What is the capital of Indonesia?', array['Jakarta','Bali','Surabaya','Bandung'], 0, 'medium'),
  ('What is the capital of the Philippines?', array['Cebu City','Manila','Davao','Quezon City'], 1, 'medium'),
  ('What is the capital of New Zealand?', array['Auckland','Christchurch','Wellington','Hamilton'], 2, 'medium'),
  ('What is the capital of Chile?', array['Valparaiso','Santiago','Concepcion','La Serena'], 1, 'easy'),
  ('What is the capital of Colombia?', array['Medellin','Bogota','Cali','Cartagena'], 1, 'medium'),
  ('What is the capital of Peru?', array['Cusco','Lima','Arequipa','Trujillo'], 1, 'easy'),
  ('What is the capital of Cuba?', array['Santiago de Cuba','Havana','Camaguey','Holguin'], 1, 'easy'),
  ('What is the capital of Morocco?', array['Casablanca','Rabat','Marrakesh','Fez'], 1, 'hard'),
