  ('What is the capital of the United Arab Emirates?', array['Dubai','Abu Dhabi','Sharjah','Ajman'], 1, 'medium'),
  ('What is the capital of Israel, as recognised by most of the international community?', array['Jerusalem','Tel Aviv','Haifa','Eilat'], 1, 'hard'),
  ('Which African country was formerly known as Abyssinia?', array['Sudan','Ethiopia','Eritrea','Somalia'], 1, 'hard'),
  ('Which country is the largest by population?', array['United States','Indonesia','India','China'], 2, 'medium'),
  ('Which is the longest mountain range in the world?', array['Rocky Mountains','Andes','Himalayas','Alps'], 1, 'medium'),
  ('Which is the tallest mountain in Africa?', array['Mount Kenya','Mount Kilimanjaro','Table Mountain','Atlas Mountains'], 1, 'easy'),
  ('Which sea lies between Europe and Africa?', array['Red Sea','Black Sea','Mediterranean Sea','Caspian Sea'], 2, 'easy'),
  ('What is the largest island in the world?', array['Madagascar','Borneo','Greenland','New Guinea'], 2, 'medium'),
