  ('Which African country has three capital cities?', array['Kenya','South Africa','Nigeria','Tanzania'], 1, 'hard'),
  ('What is the driest place on Earth?', array['Sahara Desert','Death Valley','Atacama Desert','Gobi Desert'], 2, 'hard'),
  ('Which country has the most active volcanoes?', array['Japan','Indonesia','United States','Philippines'], 1, 'hard'),
  ('Which river flows through Paris?', array['Rhine','Seine','Loire','Rhone'], 1, 'easy'),
  ('Which river flows through London?', array['Severn','Avon','Thames','Mersey'], 2, 'easy'),
  ('Which country does the island of Sicily belong to?', array['Greece','Italy','Malta','Tunisia'], 1, 'easy'),
  ('Which country has the most pyramids?', array['Egypt','Mexico','Sudan','Peru'], 2, 'hard'),
  ('Which is the largest lake in Africa?', array['Lake Tanganyika','Lake Victoria','Lake Malawi','Lake Chad'], 1, 'medium'),
  ('Which is the deepest lake in the world?', array['Lake Superior','Lake Baikal','Caspian Sea','Lake Tanganyika'], 1, 'hard'),
  ('Which mountain range separates Europe from Asia?', array['Alps','Carpathians','Ural Mountains','Caucasus'], 2, 'medium'),
  ('Which country is home to the ancient city of Petra?', array['Egypt','Jordan','Syria','Iraq'], 1, 'medium'),
  ('Which South American country is named after the explorer Amerigo Vespucci?', array['Colombia','Venezuela','Bolivia','Ecuador'], 1, 'hard'),
  ('Which European country is made up of over 17,000 islands?', array['Greece','Norway','Sweden','Denmark'], 1, 'hard'),
