  ('Which country is the Great Barrier Reef located off the coast of?', array['Indonesia','Philippines','Australia','New Zealand'], 2, 'easy'),
  ('Which is the highest waterfall in the world?', array['Niagara Falls','Angel Falls','Victoria Falls','Iguazu Falls'], 1, 'hard'),
  ('Which African country is home to Victoria Falls, shared with Zambia?', array['Zimbabwe','Botswana','Namibia','Malawi'], 0, 'medium'),
  ('Which country has the city of Timbuktu?', array['Niger','Chad','Mali','Senegal'], 2, 'hard'),
