  ('Which country shares the longest land border with China?', array['Russia','Mongolia','India','Kazakhstan'], 0, 'hard'),
  ('Which country is the setting for the ancient ruins of Machu Picchu?', array['Bolivia','Peru','Chile','Ecuador'], 1, 'easy'),
  ('Which body of water is the lowest point on Earth''s land surface?', array['Caspian Sea','Dead Sea','Sea of Galilee','Aral Sea'], 1, 'medium'),
  ('Which country is Mount Fuji located in?', array['China','Japan','South Korea','Taiwan'], 1, 'easy'),
  ('Which continent has the most countries?', array['Asia','Africa','Europe','South America'], 1, 'medium'),
  ('Which country is the world''s largest exporter of coffee?', array['Colombia','Vietnam','Brazil','Ethiopia'], 2, 'medium')
) as q(prompt, options, correct_index, difficulty)
where not exists (
  select 1 from public.questions existing where existing.prompt = q.prompt
);
